const fs=require('fs'),p=require('path'),b=process.argv[2],c=require('crypto'),f=n=>JSON.parse(fs.readFileSync(p.join(b,n),'utf8').replace(/^\uFEFF/,''));for(let n of [1,2,3,4,5]){let id='A0'+n,d=f(id+'_raport.json');console.log(id+' records');for(let x of d.controls){let expected=x.expected,obs=x.observed;let finds=x.finding_ids||x.findings||[];console.log(x.id||x.control_id,x.status,JSON.stringify(finds).slice(0,48),String(obs).slice(0,125))};let ev=d.evidence_index||d.artifacts_sha256||d.probe_index;console.log('EV shape',Array.isArray(ev)?JSON.stringify(ev[0]).slice(0,600):JSON.stringify(Object.entries(ev).slice(0,1)).slice(0,600))}

